excels.excel:

EXPORT WITH SHEET="员工薪资发放明细", HEADER=true,
    MAPPING={"a":"工号","b":"姓名","c":"部门","d":"应发工资","e":"社保公积金","f":"个人所得税","g":"实发工资"},
    FORMAT={"d":"#,##0.00","e":"#,##0.00","f":"#,##0.00","g":"#,##0.00"},
    FORMULAS={
        G2:'D2-E2-F2',G3:'D3-E3-F3',G4:'D4-E4-F4',G5:'D5-E5-F5',G6:'D6-E6-F6',
        D7:'SUM(D2:D6)',E7:'SUM(E2:E6)',F7:'SUM(F2:F6)',G7:'D7-E7-F7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
